# Bodennahe Ausbringung flüssiger Wirtschaftsdünger und Biogasgülle (o6_9)
package oepul.o6_9

eligible_technique_ids := {row.technique | some row in tables.application_techniques.eligible}

excluded_device_ids := {row.technique | some row in tables.application_techniques.excluded}

eligible_manure_type_ids := {row.manure_type | some row in tables.manure_definitions.eligible_manure_types}

allowed_biogas_feedstocks := {row.feedstock | some row in tables.manure_definitions.biogas_feedstocks}

biogas := object.get(application, "biogas_slurry", {})

application_records := object.get(application, "records", [])

# O69-MB-014: förderbar sind ausschließlich Schleppschlauch, Schleppschuh und Injektionsverfahren.
eligible_technique(t) if t in eligible_technique_ids

# O69-MB-015: Schwenkverteiler und Prallteller auf Düsenbalken werden nicht anerkannt.
excluded_devices_used := {d | some d in object.get(application, "devices_used", []); d in excluded_device_ids}

# O69-MB-007: förderbarer Wirtschaftsdünger sind Gülle, Jauche und Biogasgülle (auch mit Wasser versetzt).
non_eligible_manure_types := {m | some m in object.get(application, "manure_types", []); not m in eligible_manure_type_ids}

# O69-MB-010 / O69-MB-009: Biogasgülle nur förderbar, wenn ausschließlich definierte Ausgangsprodukte vergoren wurden.
biogas_used if object.get(biogas, "volume_m3", 0) > 0

biogas_non_defined_feedstocks := {f | some f in object.get(biogas, "feedstocks", []); not f in allowed_biogas_feedstocks}

biogas_slurry_eligible if {
	biogas_used
	count(biogas_non_defined_feedstocks) == 0
	not is_true(biogas, "contains_non_defined_components")
}

# Gesamte Biogasgülle scheidet aus, sobald ein nicht der Definition entsprechender Anteil enthalten ist.
ineligible_biogas_volume := object.get(biogas, "volume_m3", 0) if {
	biogas_used
	not biogas_slurry_eligible
}

ineligible_biogas_volume := 0 if not biogas_used

ineligible_biogas_volume := 0 if biogas_slurry_eligible

# O69-MB-008: eingeleitetes Regenwasser ist nicht förderbar; O69-MB-011: aufgemischter Festmist ist nicht förderbar.
ineligible_application_volume := (object.get(application, "rainwater_volume_m3", 0) + object.get(application, "solid_manure_with_water_volume_m3", 0)) + ineligible_biogas_volume

eligible_application_volume_raw := max2(application_volume_total - ineligible_application_volume, 0)

# O69-MB-016: chronologische, schlagbezogene Aufzeichnungen über Menge, Art, Zeitpunkt und Verfahren.
required_record_fields := ["parcel_ids", "date", "manure_type", "volume_m3", "technique"]

record_incomplete(r) if {
	some f in required_record_fields
	object.get(r, f, null) == null
}

record_incomplete(r) if count(object.get(r, "parcel_ids", [])) == 0

incomplete_records := [i | some i, r in application_records; record_incomplete(r)]

records_chronological if count(application_records) <= 1

records_chronological if {
	count(application_records) > 1
	every i in numbers.range(1, count(application_records) - 1) {
		date_ns(application_records[i - 1].date) <= date_ns(application_records[i].date)
	}
}

# O69-MB-017: Zusammenfassen mehrerer Schläge nur bei gleicher Kultur, Menge, Datum und Ausbringungsart; Schlaggrößen addieren.
parcel_area(pid) := a if {
	some p in parcels
	p.parcel_id == pid
	a := p.area_ha
}

aggregated_record_invalid(r) if {
	count(r.parcel_ids) > 1
	count({c | some c in object.get(r, "crops", [])}) != 1
}

aggregated_record_invalid(r) if {
	count(r.parcel_ids) > 1
	has_value(r, "area_ha")
	areas := [parcel_area(pid) | some pid in r.parcel_ids]
	count(areas) == count(r.parcel_ids)
	abs(sum(areas) - r.area_ha) > 0.0001
}

invalid_aggregated_records := [i | some i, r in application_records; aggregated_record_invalid(r)]

# Abgleich: beantragte Menge je Verfahren darf die aufgezeichnete Menge nicht übersteigen (O69-GEN-021).
recorded_volume_by_technique[t] := s if {
	some t in eligible_technique_ids
	s := sum([r.volume_m3 | some r in application_records; r.technique == t])
}

volume_not_documented[t] := claimed - recorded if {
	count(application_records) > 0
	some t, claimed in claimed_application_volumes
	recorded := recorded_volume_by_technique[t]
	claimed > recorded
}

# O69-MB-013: Ausbringung auf Acker- oder Grünlandflächen des Betriebes.
records_on_non_farm_or_ineligible_land := [i |
	some i, r in application_records
	some pid in object.get(r, "parcel_ids", [])
	not parcel_is_farm_arable_or_grassland(pid)
]

parcel_is_farm_arable_or_grassland(pid) if {
	some p in parcels
	p.parcel_id == pid
	p.land_use in {"arable", "grassland"}
}

violations contains {"rule_id": "O69-MB-014", "message": sprintf("Aufzeichnung %d: Ausbringungstechnik nicht förderbar", [i])} if {
	some i, r in application_records
	not eligible_technique(r.technique)
}

violations contains {"rule_id": "O69-MB-015", "message": sprintf("Nicht anerkanntes Ausbringungsgerät verwendet: %v", [d])} if {
	some d in excluded_devices_used
}

violations contains {"rule_id": "O69-MB-007", "message": sprintf("Nicht förderbarer Wirtschaftsdünger: %v", [m])} if {
	some m in non_eligible_manure_types
}

violations contains {"rule_id": "O69-MB-010", "message": "Biogasgülle enthält nicht der Definition entsprechende Bestandteile – gesamte Biogasgülle nicht förderfähig"} if {
	biogas_used
	not biogas_slurry_eligible
}

violations contains {"rule_id": "O69-MB-020", "message": "Für die Biogasgülle fehlen geeignete Nachweise über die Ausgangsprodukte"} if {
	biogas_used
	not is_true(biogas, "feedstock_proof_available")
}

violations contains {"rule_id": "O69-MB-011", "message": "Mit Wasser versetzter und aufgemischter Festmist ist nicht förderbar"} if {
	object.get(application, "solid_manure_with_water_volume_m3", 0) > 0
}

violations contains {"rule_id": "O69-MB-008", "message": "In die Güllegrube eingeleitetes Regenwasser ist nicht förderbar"} if {
	object.get(application, "rainwater_volume_m3", 0) > 0
}

violations contains {"rule_id": "O69-MB-016", "message": "Schlagbezogene Ausbringungsaufzeichnungen fehlen"} if {
	application_volume_total > 0
	count(application_records) == 0
}

violations contains {"rule_id": "O69-MB-016", "message": sprintf("Aufzeichnung %d unvollständig (Schlag, Datum, Art, Menge, Verfahren)", [i])} if {
	some i in incomplete_records
}

violations contains {"rule_id": "O69-MB-016", "message": "Ausbringungsaufzeichnungen sind nicht chronologisch geführt"} if {
	count(application_records) > 1
	count(incomplete_records) == 0
	not records_chronological
}

violations contains {"rule_id": "O69-MB-017", "message": sprintf("Aufzeichnung %d: unzulässige Zusammenfassung mehrerer Schläge", [i])} if {
	some i in invalid_aggregated_records
}

violations contains {"rule_id": "O69-GEN-021", "message": sprintf("Beantragte Menge (%v) übersteigt aufgezeichnete Menge um %v m³", [t, d])} if {
	some t, d in volume_not_documented
}

violations contains {"rule_id": "O69-MB-013", "message": sprintf("Aufzeichnung %d: Ausbringung nicht auf Acker- oder Grünlandfläche des Betriebes", [i])} if {
	some i in records_on_non_farm_or_ineligible_land
}

violations contains {"rule_id": "O69-MB-018", "message": "Ausbringung durch betriebsfremde Geräte ohne Rechnung oder gleichwertige Unterlagen"} if {
	is_true(application, "contractor_used")
	not is_true(application, "contractor_invoice_available")
}

violations contains {"rule_id": "O69-MB-019", "message": "Gemeinschaftlich angeschafftes Güllefass: Gerät nicht kontrollierbar oder Rechnung nicht an teilnehmende Betriebe ausgestellt"} if {
	shared := object.get(application, "shared_equipment", {})
	is_true(shared, "used")
	shared_equipment_conditions_unmet(shared)
}

shared_equipment_conditions_unmet(shared) if not is_true(shared, "available_or_controllable")

shared_equipment_conditions_unmet(shared) if not is_true(shared, "invoice_issued_to_participants")

# Allgemeine Teilnahmebedingungen ÖPUL 2023, SRL Allgemeiner Teil, GSP-AV, NAPV und Meldungen 2026 (o6_9)
package oepul.o6_9

farm := object.get(input, "farm", {})

gc := tables.general_conditions

measure_requested if count(measure) > 0

# O69-GEN-001: förderwerbende Personen; Gebietskörperschaften nicht förderfähig (Maßnahme 9 ist keine Ausnahme).
applicant_type := object.get(farm, "applicant_type", "natural_person")

applicant_type_row := row if {
	some row in gc.eligible_applicant_types
	row.applicant_type == applicant_type
}

public_body_exception_applies if {
	some m in gc.public_body_exception_measures
	m.code == measure_codes.srl_measure
}

applicant_eligible if {
	applicant_type_row.max_public_body_share_percent == null
}

applicant_eligible if {
	applicant_type_row.max_public_body_share_percent != null
	object.get(farm, "public_body_share_percent", 0) <= applicant_type_row.max_public_body_share_percent
}

applicant_eligible if {
	applicant_type == "public_body"
	public_body_exception_applies
}

# O69-GEN-002: Betrieb im eigenen Namen und auf eigene Rechnung, aktiver Landwirt, landwirtschaftliche Tätigkeit.
applicant_status_unmet contains "own_name_and_account" if is_false(farm, "manages_in_own_name_and_account")

applicant_status_unmet contains "active_farmer" if is_false(farm, "is_active_farmer")

applicant_status_unmet contains "agricultural_activity" if is_false(farm, "exercises_agricultural_activity")

# O69-GEN-003 / O69-GEN-004: Betriebsmindestgröße nur im ersten ÖPUL-Teilnahmejahr.
first_oepul_year if object.get(farm, "oepul_first_participation_year", 0) == year

minimum_farm_size_met if not first_oepul_year

minimum_farm_size_met if {
	first_oepul_year
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= gc.minimum_farm_size_first_year.protected_cultivation_ha
}

minimum_farm_size_met if {
	first_oepul_year
	total_area_ha >= gc.minimum_farm_size_first_year.agricultural_area_ha
}

# O69-GEN-005: Flächen in Österreich, Tiere in Österreich gehalten.
animals_abroad := [i | some i, g in species_groups; is_false(g, "kept_in_austria")]

# O69-GEN-006 / O69-NOT-001 / O69-NOT-002: Mindestbewirtschaftung auf Ackerflächen (Ernte >= 85 %), Dürre 2026.
drought_district_match(state, district) if {
	some row in tables.drought_2026_districts.rows
	row.federal_state == state
	row.district in {"*", district}
}

parcel_region(p) := [object.get(p, "federal_state", object.get(farm, ["region", "federal_state"], "")), object.get(p, "district", object.get(farm, ["region", "district"], ""))]

harvest_obligation_waived_2026(p) if {
	year == tables.drought_2026_districts.year
	[state, district] := parcel_region(p)
	drought_district_match(state, district)
	is_true(p, "no_harvestable_crop_due_to_drought")
	is_true(p, "late_summer_or_autumn_harvest_crop")
}

minimum_management_unmet(p) if {
	p.land_use == "arable"
	not object.get(p, ["crop", "crop_category"], "") == "fallow"
	object.get(p, "harvest_share", 1) < 0.85
	not harvest_obligation_waived_2026(p)
	not is_true(p, "force_majeure_recognised")
}

# O69-GEN-008: Code OP – keine ÖPUL-Prämie; O69-GEN-007: nicht förderfähige Flächen.
op_coded(p) if {
	some c in object.get(p, "oepul_codes", [])
	c in {"OP", "OP9", "VF"}
}

parcel_premium_eligible(p) if {
	not op_coded(p)
	not minimum_management_unmet(p)
	not is_true(p, "non_eligible_area")
	not is_true(p, "in_national_park")
	not is_false(p, "located_in_austria")
}

# O69-GEN-017 / O69-SRL-009: Einzelflächenkombination gemäß Anhang L.
non_combinable_measures := {row.other_measure | some row in tables.combination_table.rows; not row.combinable}

combination_conflicts contains {"parcel_id": p.parcel_id, "measure": m} if {
	some p in parcels
	"9" in object.get(p, "oepul_measures", [])
	some m in object.get(p, "oepul_measures", [])
	m in non_combinable_measures
}

combination_conflicts contains {"parcel_id": p.parcel_id, "measure": "GA_pot_substrate"} if {
	some p in parcels
	"9" in object.get(p, "oepul_measures", [])
	is_true(p, "protected_cultivation_pot_or_substrate")
}

# O69-GEN-024b: Obergrenze für Flächenzahlungen je Schlag.
area_payment_cap(scope, y) := row.cap_eur_per_ha if {
	some row in gc.area_payment_caps
	row.scope == scope
	y >= row.year_from
	rate_row_open_or_covers(row, y)
}

area_cap_exceeded_parcels contains p.parcel_id if {
	some p in parcels
	has_value(p, "area_payments_eur_per_ha")
	p.area_payments_eur_per_ha > area_payment_cap("general", year)
}

# O69-GEN-026: höhere Gewalt binnen drei Wochen melden.
force_majeure := object.get(measure, "force_majeure", {})

force_majeure_notified_in_time if {
	has_value(force_majeure, "able_to_notify_date")
	has_value(force_majeure, "notified_date")
	date_ns(force_majeure.notified_date) - date_ns(force_majeure.able_to_notify_date) <= ((gc.force_majeure_notification_weeks * 7) * 24) * 3600000000000
}

# O69-NAPV-002 / O69-NAPV-003: Abgleich der Ausbringungsaufzeichnungen mit NAPV-Verbotszeiträumen und Bodenzustand.
in_period(md, start_md, end_md) if {
	start_md > end_md
	md >= start_md
}

in_period(md, start_md, end_md) if {
	start_md > end_md
	md <= end_md
}

record_land_scope(r) := "grassland_and_arable_forage" if object.get(r, "land_use", "") == "grassland"

record_land_scope(r) := "grassland_and_arable_forage" if {
	object.get(r, "land_use", "") == "arable"
	is_true(r, "arable_forage")
}

record_land_scope(r) := "arable_excluding_forage" if {
	object.get(r, "land_use", "") == "arable"
	not is_true(r, "arable_forage")
}

napv_ban_conflicts contains i if {
	some i, r in application_records
	has_value(r, "date")
	scope := record_land_scope(r)
	some period in tables.fertilizable_area.napv_application_ban_periods
	period.land_scope == scope
	in_period(month_day(r.date), napv_ban_start(period, r), napv_ban_end(period, r))
}

napv_ban_start(period, r) := period.ban_start_month_day if not is_true(r, "napv_late_application_exception")

napv_ban_start(period, r) := "11-01" if {
	is_true(r, "napv_late_application_exception")
	period.extended_until_month_day != null
}

napv_ban_start(period, r) := period.ban_start_month_day if {
	is_true(r, "napv_late_application_exception")
	period.extended_until_month_day == null
}

napv_ban_end(period, r) := period.early_end_month_day if {
	is_true(r, "napv_early_demand_crop")
	period.early_end_month_day != null
}

napv_ban_end(period, r) := period.ban_end_month_day if not napv_early_end_applies(period, r)

napv_early_end_applies(period, r) if {
	is_true(r, "napv_early_demand_crop")
	period.early_end_month_day != null
}

napv_soil_conflicts contains i if {
	some i, r in application_records
	object.get(r, "soil_state", "normal") in {"frozen", "water_saturated", "flooded", "snow_covered"}
}

violations contains {"rule_id": "O69-GEN-001", "message": "Förderwerbende Person kommt für die Maßnahme nicht in Betracht"} if {
	measure_requested
	not applicant_eligible
}

violations contains {"rule_id": "O69-GEN-002", "message": sprintf("Persönliche Fördervoraussetzung nicht erfüllt: %v", [c])} if {
	measure_requested
	some c in applicant_status_unmet
}

violations contains {"rule_id": "O69-GEN-003", "message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht"} if {
	measure_requested
	not minimum_farm_size_met
}

violations contains {"rule_id": "O69-GEN-005", "message": "Flächen außerhalb Österreichs werden nicht gefördert"} if {
	measure_requested
	is_false(farm, "all_areas_in_austria")
}

violations contains {"rule_id": "O69-GEN-005", "message": sprintf("Tiergruppe %d nicht in Österreich gehalten – nicht anrechenbar", [i])} if {
	measure_requested
	some i in animals_abroad
}

violations contains {"rule_id": "O69-GEN-017", "message": sprintf("Schlag %v: Maßnahme 9 nicht kombinierbar mit %v", [c.parcel_id, c.measure])} if {
	some c in combination_conflicts
}

violations contains {"rule_id": "O69-GEN-028", "message": "Kontrolle verweigert oder verhindert – Antrag abzulehnen, Verträge beenden und rückabwickeln"} if {
	is_true(measure, "controls_refused")
	not is_true(force_majeure, "occurred")
}

violations contains {"rule_id": "O69-GEN-026", "message": "Höhere Gewalt nicht binnen drei Wochen gemeldet"} if {
	is_true(force_majeure, "occurred")
	not force_majeure_notified_in_time
}

violations contains {"rule_id": "O69-GEN-009", "message": "Förderverpflichtungen nicht während der gesamten Verpflichtungsdauer erfüllt"} if {
	measure_requested
	not commitment_fulfilled_whole_year
}

violations contains {"rule_id": "O69-GEN-036", "message": "Leistung wird bereits aus anderem öffentlichen Titel gefördert oder ist gesetzlich/behördlich vorgeschrieben"} if {
	is_true(measure, "same_service_funded_or_prescribed_otherwise")
}

warnings contains {"rule_id": "O69-NAPV-002", "message": sprintf("Aufzeichnung %d: Ausbringung im NAPV-Verbotszeitraum", [i])} if {
	some i in napv_ban_conflicts
}

warnings contains {"rule_id": "O69-NAPV-003", "message": sprintf("Aufzeichnung %d: Ausbringung auf gefrorenen, wassergesättigten, überschwemmten oder schneebedeckten Boden", [i])} if {
	some i in napv_soil_conflicts
}

warnings contains {"rule_id": "O69-GEN-024", "message": "Auszahlungsbetrag überschreitet 50 € nicht – von der Gewährung kann abgesehen werden"} if {
	measure_requested
	below_minimum_payment
}

warnings contains {"rule_id": "O69-GEN-024b", "message": sprintf("Schlag %v: Obergrenze für Flächenzahlungen überschritten", [pid])} if {
	some pid in area_cap_exceeded_parcels
}

warnings contains {"rule_id": "O69-GEN-006", "message": sprintf("Schlag %v: Ernte auf weniger als 85 %% – keine Prämie auf diesem Schlag", [p.parcel_id])} if {
	participates_pig_feeding
	some p in parcels
	minimum_management_unmet(p)
}

warnings contains {"rule_id": "O69-NOT-001", "message": sprintf("Schlag %v: Ernteverpflichtung 2026 dürrebedingt automatisch als höhere Gewalt anerkannt", [p.parcel_id])} if {
	some p in parcels
	harvest_obligation_waived_2026(p)
}

# Pflichten (Dokumentations-, Melde- und Aufbewahrungspflichten) für teilnehmende Betriebe.
obligations contains {"rule_id": "O69-MB-016", "obligation": "Chronologische, schlagbezogene Aufzeichnungen über Menge, Art, Zeitpunkt und Verfahren der bodennahen Ausbringung führen"} if {
	application_volume_total > 0
}

obligations contains {"rule_id": "O69-MB-023", "obligation": "Aufzeichnungen über Datum und Menge der Gülleseparierung führen"} if {
	separated_volume_claimed > 0
}

obligations contains {"rule_id": "O69-MB-019", "obligation": "Einsatz gemeinschaftlicher Geräte idealerweise mit Kubikmeter- bzw. Einsatzstundenzähler im Betriebsbuch dokumentieren (Empfehlung)"} if {
	shared_equipment_in_use
}

shared_equipment_in_use if is_true(object.get(application, "shared_equipment", {}), "used")

shared_equipment_in_use if is_true(object.get(separation, "shared_equipment", {}), "used")

obligations contains {"rule_id": "O69-MB-039", "obligation": "Ausstieg der AMA online über eAMA im Rahmen des aktuellen Mehrfachantrages bekannt geben"} if {
	measure_requested
}

obligations contains {"rule_id": "O69-GEN-016", "obligation": "Förderverpflichtungen bis zum Ausstieg einhalten"} if {
	measure_requested
}

obligations contains {"rule_id": "O69-GEN-027", "obligation": sprintf("Förderrelevante Unterlagen bis Ende %d aufbewahren (4 Jahre ab Ende des Kalenderjahres der Zahlung)", [year + gc.records_retention_years_one_year_measures])} if {
	measure_requested
}

obligations contains {"rule_id": "O69-GEN-032", "obligation": "Änderungen der tatsächlichen oder rechtlichen Verhältnisse unverzüglich melden; Betriebsübertragung binnen vier Wochen anzeigen"} if {
	measure_requested
}

obligations contains {"rule_id": "O69-GEN-037", "obligation": "Konditionalität (Klima/Umwelt, öffentliche Gesundheit, Pflanzengesundheit, Tierwohl) und soziale Konditionalität einhalten"} if {
	measure_requested
}

obligations contains {"rule_id": "O69-GEN-028", "obligation": "Kontrollen zulassen, Auskunftsperson stellen und förderrelevante Unterlagen vorlegen"} if {
	measure_requested
}

obligations contains {"rule_id": "O69-MB-029", "obligation": "Rezepturen mit Rohproteingehalt je kg Futtermittel (88 % TM) vorhalten; Phasenfütterung bei VOK plausibel machen"} if {
	participates_pig_feeding
}

# Teilnahme, Vertragszeitraum, Fristen, Ausstieg und Übernahme (o6_9)
package oepul.o6_9

# O69-MB-001: Maßnahmenkategorien; stark N-reduzierte Fütterung erst ab Antragsjahr 2025.
measure_categories contains "slurry_application"

measure_categories contains "slurry_separation"

measure_categories contains "n_reduced_pig_feeding" if year >= 2025

# O69-MB-002 / O69-GEN-010: einjähriger Vertrags- und Verpflichtungszeitraum mit automatischer Verlängerung.
contract_period := {
	"start": year_date(year, "01-01"),
	"end": year_date(year, "12-31"),
	"duration": "calendar_year",
	"auto_renewal": auto_renewal,
}

default auto_renewal := true

auto_renewal := false if deregistered_for_year

is_one_year_measure if {
	some m in tables.general_conditions.one_year_measures
	m.code == measure_codes.srl_measure
}

# Eligible application volumes as claimed in the MFA ("MFA-Angaben"), per technique.
claimed_application_volumes[t] := v if {
	some row in tables.application_techniques.eligible
	t := row.technique
	v := object.get(application, ["volumes_m3", t], 0)
}

application_volume_total := sum([v | some t, v in claimed_application_volumes])

# O69-MB-036 / O69-GSP-003: prämienfähige Mengenbeantragung bis 30. November des Förderjahres.
quantity_claim_deadline := year_date(year, tables.deadlines.quantity_claim.month_day)

quantity_claim_timely(obj) if not has_value(obj, "quantity_claim_date")

quantity_claim_timely(obj) if date_on_or_before(obj.quantity_claim_date, quantity_claim_deadline)

claims_application_volume if {
	application_volume_total > 0
	quantity_claim_timely(application)
}

claims_separation_volume if {
	object.get(separation, "separated_volume_m3", 0) > 0
	quantity_claim_timely(separation)
}

participates_pig_feeding if {
	is_true(pig_feeding, "participates")
	year >= 2025
}

# O69-MB-004 / O69-MB-012: Mindestteilnahme – mindestens eine Maßnahmenkategorie je Teilnahmejahr.
minimum_participation_met if claims_application_volume

minimum_participation_met if claims_separation_volume

minimum_participation_met if participates_pig_feeding

# O69-MB-003: Vertrag erlischt, wenn keine Menge beantragt und nicht an der Schweinefütterung teilgenommen wird.
contract_lapsed if not minimum_participation_met

new_measure_application_required_for_next_year if contract_lapsed

# O69-MB-030 / O69-GEN-012 / O69-GSP-002: Maßnahmenantrag bis 31.12. vor Vertragsbeginn.
contract_start_year := object.get(measure, "contract_start_year", year)

measure_application_deadline(start_year) := year_date(start_year - 1, tables.deadlines.measure_application.month_day)

measure_application_timely if {
	has_value(measure, "measure_application_date")
	date_on_or_before(measure.measure_application_date, measure_application_deadline(contract_start_year))
}

# O69-MB-031 / O69-GEN-011 / O69-SRL-010: letzter Einstieg in die Maßnahme mit Förderjahr 2027.
last_entry_measure := [e | some e in tables.deadlines.last_entry; e.scope == "measure"][0]

last_entry_pig_feeding := [e | some e in tables.deadlines.last_entry; e.scope == "n_reduced_pig_feeding"][0]

measure_entry_year_allowed if {
	contract_start_year >= 2023
	contract_start_year <= last_entry_measure.last_contract_year
}

# O69-MB-032: letzter Einstieg in die Schweinefütterung mit Förderjahr 2028, nur bei gültiger Teilnahme an der Maßnahme.
pig_feeding_start_year := object.get(pig_feeding, "start_year", year)

pig_feeding_application_timely if {
	has_value(pig_feeding, "application_date")
	date_on_or_before(pig_feeding.application_date, measure_application_deadline(pig_feeding_start_year))
}

pig_feeding_entry_allowed if {
	pig_feeding_start_year >= last_entry_pig_feeding.first_contract_year
	pig_feeding_start_year <= last_entry_pig_feeding.last_contract_year
	measure_application_timely
	measure_entry_year_allowed
}

# O69-MB-040 / O69-GEN-013: Abmeldung im laufenden Jahr macht die Maßnahme im betroffenen Förderjahr ungültig.
deregistered_for_year if {
	has_value(measure, "deregistration_date")
	date_year(measure.deregistration_date) == year
}

# O69-MB-038: Ausstieg nach Erfüllung des einjährigen Vertragszeitraumes möglich (frühestens ab 1. Jänner des Folgejahres).
earliest_deregistration_date_without_loss := year_date(year + 1, "01-01")

# O69-GEN-014: Ausstieg bis zur Durchführung/Ankündigung einer VOK oder Mitteilung des Ergebnisses einer Verwaltungskontrolle.
exit_blocked_by_control if {
	has_value(measure, "deregistration_date")
	has_value(measure, "control_announced_date")
	date_ns(measure.control_announced_date) <= date_ns(measure.deregistration_date)
}

# O69-GEN-015: Wiedereinstieg nach Ausstieg, Ausschluss oder Nichtabgabe nur mit neuem Maßnahmenantrag.
reentry_requires_new_measure_application if contract_lapsed

reentry_requires_new_measure_application if deregistered_for_year

reentry_requires_new_measure_application if is_true(measure, "excluded_from_measure")

reentry_requires_new_measure_application if is_true(measure, "multiple_application_not_submitted_previous_year")

# O69-GEN-018 / O69-GEN-019: Maßnahmenübernahme nur in Einzelfällen (Betriebsauflösung, -teilung, -zusammenlegung).
takeover := object.get(measure, "takeover", {})

takeover_deadline(y) := year_date(y, tables.deadlines.measure_takeover.exception_years[sprintf("%d", [y])])

takeover_deadline(y) := year_date(y, tables.deadlines.measure_takeover.month_day) if {
	not tables.deadlines.measure_takeover.exception_years[sprintf("%d", [y])]
}

takeover_allowed if {
	is_true(takeover, "is_takeover")
	takeover.reason in tables.general_conditions.single_case_takeover_reasons
	is_true(takeover, "animals_and_areas_same_previous_farm")
	date_on_or_before(takeover.date, takeover_deadline(year))
}

# Verstöße der Teilnahme- und Fristenregeln
violations contains {"rule_id": "O69-MB-030", "message": "Maßnahmenantrag fehlt oder wurde nicht bis 31. Dezember vor Vertragsbeginn gestellt"} if {
	measure_requested
	not measure_application_timely
}

violations contains {"rule_id": "O69-MB-031", "message": "Einstieg in die Maßnahme nach dem Förderjahr 2027 nicht mehr möglich"} if {
	measure_requested
	not measure_entry_year_allowed
}

violations contains {"rule_id": "O69-MB-032", "message": "Einstieg in die stark stickstoffreduzierte Fütterung von Schweinen nicht zulässig oder nicht fristgerecht beantragt"} if {
	is_true(pig_feeding, "participates")
	not pig_feeding_entry_allowed
}

violations contains {"rule_id": "O69-MB-032", "message": "Maßnahmenkategorie Schweinefütterung nicht fristgerecht bis 31. Dezember vor Teilnahmebeginn beantragt"} if {
	is_true(pig_feeding, "participates")
	not pig_feeding_application_timely
}

violations contains {"rule_id": "O69-MB-003", "message": "Keine Menge beantragt und keine Teilnahme an der Schweinefütterung – Vertrag erlischt"} if {
	measure_requested
	contract_lapsed
}

violations contains {"rule_id": "O69-MB-036", "message": "Bodennah ausgebrachte Mengen nach dem 30. November beantragt – nicht prämienfähig"} if {
	application_volume_total > 0
	not quantity_claim_timely(application)
}

violations contains {"rule_id": "O69-MB-036", "message": "Separierte Güllemenge nach dem 30. November beantragt – nicht prämienfähig"} if {
	object.get(separation, "separated_volume_m3", 0) > 0
	not quantity_claim_timely(separation)
}

violations contains {"rule_id": "O69-MB-040", "message": "Abmeldung im laufenden Förderjahr – Maßnahme im betroffenen Förderjahr nicht gültig"} if {
	deregistered_for_year
}

violations contains {"rule_id": "O69-GEN-014", "message": "Ausstieg nach Ankündigung/Durchführung einer Kontrolle ist nicht mehr möglich"} if {
	exit_blocked_by_control
}

violations contains {"rule_id": "O69-GEN-018", "message": "Maßnahmenübernahme nur in Einzelfällen bei Betriebsauflösung, -teilung oder -zusammenlegung fristgerecht und mit Tieren und Flächen desselben Vorbetriebs möglich"} if {
	is_true(takeover, "is_takeover")
	not takeover_allowed
}

# O69-GSP-004: Fristende am Wochenende/Feiertag verschiebt sich nicht für Maßnahmenantrag (31.12.) und Mengenbeantragung (30.11.).
default deadline_weekend_extension_applies := false

deadline_weekend_extension_applies if tables.deadlines.measure_application.weekend_extension == true

deadline_weekend_extension_applies if tables.deadlines.quantity_claim.weekend_extension == true

# O69-GSP-005: Änderungen nach Ablauf der Fristen nur ohne Prämienerhöhung, vor Hinweis auf Verstoß bzw. VOK-Ankündigung.
post_deadline_correction_allowed(change) if {
	not is_true(change, "increases_premium")
	not is_true(change, "after_control_notice_or_finding")
	is_true(change, "still_verifiable")
}

# O69-SRL-012: Revisionsklausel – Ablehnung einer Vertragsanpassung beendet den Vertrag ohne Rückforderung für die Vergangenheit.
revision_clause_contract_ended if is_true(measure, "revision_adaptation_refused")

revision_clause_repayment_for_past := false if revision_clause_contract_ended

# O69-MB-037: Abgabe des Mehrfachantrages bis 15. April (2023 und 2028: 17. April).
multiple_application_deadline(y) := year_date(y, tables.deadlines.multiple_application.exception_years[sprintf("%d", [y])])

multiple_application_deadline(y) := year_date(y, tables.deadlines.multiple_application.month_day) if {
	not tables.deadlines.multiple_application.exception_years[sprintf("%d", [y])]
}

# O69-GEN-009: förderfähig nur, wenn die Verpflichtungen während der gesamten Verpflichtungsdauer erfüllt werden.
default commitment_fulfilled_whole_year := true

commitment_fulfilled_whole_year := false if is_false(measure, "obligations_fulfilled_whole_year")

# O69-GEN-033: Betriebsübertragung nach Einreichung des MFA – Beihilfe an den Übergeber, sofern Bedingungen im übertragenen Betrieb erfüllt.
farm_transfer_payment_recipient := "transferor" if {
	is_true(measure, "farm_transferred_after_mfa")
	is_true(measure, "all_conditions_met_in_transferred_farm")
}

# Stark stickstoffreduzierte Fütterung von Schweinen ab dem Antragsjahr 2025 (o6_9)
package oepul.o6_9

cp_limits := tables.pig_crude_protein_limits

rations := object.get(pig_feeding, "rations", [])

held_ration_categories := {c | some c in object.get(pig_feeding, "held_categories", [])}

fattening_categories := {c | some c in cp_limits.fattening_group_categories}

# O69-MB-005 / O69-MB-006 / O69-SRL-002: mindestens 1,00 GVE Schweine im Jahresdurchschnitt je ha Ackerfläche (ohne Abzüge).
pig_gve := pig_feeding.pig_gve_annual_average if has_value(pig_feeding, "pig_gve_annual_average")

pig_gve := sum([species_group_gve(g, "gve") | some g in species_groups; g.species == "pigs"]) if {
	not has_value(pig_feeding, "pig_gve_annual_average")
}

pig_gve_per_arable_ha := pig_gve / arable_area_ha if arable_area_ha > 0

pig_feeding_access_met if pig_gve_per_arable_ha >= 1.0

# O69-MB-026: Rohproteingrenzen je kg Ration (88 % TM) gemäß Tabelle.
cp_limit(category) := row.max_crude_protein_g_per_kg_88dm if {
	some row in cp_limits.rows
	row.animal_category == category
}

ration_value(category) := r.crude_protein_g_per_kg_88dm if {
	some r in rations
	r.animal_category == category
}

non_fattening_ration_exceeded contains category if {
	some r in rations
	category := r.animal_category
	not category in fattening_categories
	r.crude_protein_g_per_kg_88dm > cp_limit(category)
}

# O69-MB-027: Mastgruppe – entweder Durchschnittswert (max. 157 g) oder Phasenfütterung je Gewichtsabschnitt.
fattening_average_compliant if {
	has_value(pig_feeding, "fattening_average_crude_protein_g_per_kg_88dm")
	pig_feeding.fattening_average_crude_protein_g_per_kg_88dm <= cp_limits.fattening_group_average_max_g
}

held_fattening_categories := held_ration_categories & fattening_categories

fattening_phase_compliant if {
	count(held_fattening_categories) > 0
	every c in held_fattening_categories {
		ration_value(c) <= cp_limit(c)
	}
}

fattening_group_compliant if count(held_fattening_categories) == 0

fattening_group_compliant if fattening_average_compliant

fattening_group_compliant if fattening_phase_compliant

uses_phase_feeding if {
	count(held_fattening_categories) > 0
	not fattening_average_compliant
	fattening_phase_compliant
}

# Alle am Betrieb gehaltenen Schweine (nicht Mastgruppe) benötigen eine dokumentierte Ration.
missing_rations contains c if {
	some c in held_ration_categories
	not c in fattening_categories
	not ration_value(c)
}

# O69-MB-028: Berechnungsgrundlage Futtermitteluntersuchung, Standardwerte Fachliteratur oder Herstellerangabe.
valid_protein_value_bases := {"feed_analysis", "standard_literature_value", "manufacturer_declaration"}

invalid_protein_basis contains r.animal_category if {
	some r in rations
	not object.get(r, "protein_value_basis", "") in valid_protein_value_bases
}

pig_feeding_compliant if {
	count(non_fattening_ration_exceeded) == 0
	fattening_group_compliant
	count(missing_rations) == 0
}

# O69-MB-033 / O69-SRL-008: keine gleichzeitige Teilnahme an Kategorie (9) und Zuschlag (16).
pig_feeding_combination_conflict if {
	participates_pig_feeding
	is_true(measure, "participates_gwa_n_reduced_feeding_topup")
}

pig_feeding_premium_eligible if {
	participates_pig_feeding
	pig_feeding_access_met
	pig_feeding_compliant
	not pig_feeding_combination_conflict
}

violations contains {"rule_id": "O69-MB-005", "message": sprintf("Weniger als 1,00 GVE Schweine je ha Ackerfläche (%v)", [round2(pig_gve_per_arable_ha)])} if {
	participates_pig_feeding
	not pig_feeding_access_met
	pig_gve_per_arable_ha
}

violations contains {"rule_id": "O69-MB-005", "message": "GVE Schweine je ha Ackerfläche nicht ermittelbar (Ackerfläche fehlt)"} if {
	participates_pig_feeding
	not pig_gve_per_arable_ha
}

violations contains {"rule_id": "O69-MB-026", "message": sprintf("Rohproteingrenze überschritten: %v", [c])} if {
	participates_pig_feeding
	some c in non_fattening_ration_exceeded
}

violations contains {"rule_id": "O69-MB-027", "message": "Mastgruppe: weder Durchschnittswert (max. 157 g) noch Phasengrenzen eingehalten"} if {
	participates_pig_feeding
	not fattening_group_compliant
}

violations contains {"rule_id": "O69-MB-026", "message": sprintf("Keine Ration für gehaltene Tierkategorie dokumentiert: %v", [c])} if {
	participates_pig_feeding
	some c in missing_rations
}

violations contains {"rule_id": "O69-MB-028", "message": sprintf("Unzulässige Grundlage für Rohproteingehalt: %v", [c])} if {
	participates_pig_feeding
	some c in invalid_protein_basis
}

violations contains {"rule_id": "O69-MB-029", "message": "Kein Nachweis über Rezepturen mit Rohproteingehalt je kg Futtermittel (88 % TM)"} if {
	participates_pig_feeding
	not is_true(pig_feeding, "recipe_evidence_available")
}

violations contains {"rule_id": "O69-MB-029", "message": "Phasenfütterung nicht als technisch möglich und tatsächlich durchgeführt plausibilisiert"} if {
	participates_pig_feeding
	uses_phase_feeding
	not is_true(pig_feeding, "phase_feeding_plausible")
}

violations contains {"rule_id": "O69-MB-033", "message": "Gleichzeitige Teilnahme an 'Stark stickstoffreduzierte Fütterung von Schweinen' (9) und dem gleichlautenden Zuschlag (16) nicht möglich"} if {
	pig_feeding_combination_conflict
}

violations contains {"rule_id": "O69-MB-001", "message": "Stark stickstoffreduzierte Fütterung von Schweinen erst ab Antragsjahr 2025 möglich"} if {
	is_true(pig_feeding, "participates")
	year < 2025
}

# Gülleseparation von am Betrieb angefallener Rindergülle (o6_9)
package oepul.o6_9

separation_records := object.get(separation, "records", [])

separated_volume_claimed := object.get(separation, "separated_volume_m3", 0)

# O69-MB-021 / O69-MB-022: nur am Betrieb durch Rinderhaltung angefallene, tatsächlich separierte Gülle ist förderbar.
separation_ineligible_volume := object.get(separation, "external_cattle_slurry_m3", 0) + object.get(separation, "non_cattle_slurry_m3", 0)

eligible_separation_volume_raw := max2(separated_volume_claimed - separation_ineligible_volume, 0)

# O69-MB-043 / O69-SRL-006: Rinder-GVE aus der Rinderdatenbank, unabhängig vom Aufstallungssystem.
cattle_gve := measure.cattle_gve_annual_average if has_value(measure, "cattle_gve_annual_average")

cattle_gve := sum([species_group_gve(g, "rgve") | some g in species_groups; g.species == "cattle"]) if {
	not has_value(measure, "cattle_gve_annual_average")
}

# GVE einer Tiergruppe: angegebener GVE-Wert, sonst Stückzahl (Jahresdurchschnitt) x Faktor gemäß Anhang A.
species_group_gve(g, _) := g.gve if has_value(g, "gve")

species_group_gve(g, column) := animal_count_for_gve(g) * gve_factor(g.species, g.category, column) if {
	not has_value(g, "gve")
}

animal_count_for_gve(g) := g.annual_average_count if has_value(g, "annual_average_count")

animal_count_for_gve(g) := object.get(g, "animal_count", 0) if not has_value(g, "annual_average_count")

gve_factor(species, category, column) := f if {
	some row in tables.gve_key.rows
	row.species == species
	row.category == category
	f := row[column]
	f != null
}

separation_cap_m3 := tables.premium_rates.caps.separation_m3_per_cattle_gve * cattle_gve

violations contains {"rule_id": "O69-MB-021", "message": "Gülleseparation muss mittels mechanischer Einrichtung in feste und flüssige Phase erfolgen"} if {
	separated_volume_claimed > 0
	is_false(separation, "mechanical_separation")
}

violations contains {"rule_id": "O69-MB-022", "message": "Betriebsfremde Rindergülle bzw. Nicht-Rindergülle ist bei der Gülleseparation nicht förderbar"} if {
	separation_ineligible_volume > 0
}

violations contains {"rule_id": "O69-MB-023", "message": "Aufzeichnungen über Datum und Menge der Gülleseparierung fehlen oder sind unvollständig"} if {
	separated_volume_claimed > 0
	count(separation_records) == 0
}

violations contains {"rule_id": "O69-MB-023", "message": sprintf("Separationsaufzeichnung %d ohne Datum oder Menge", [i])} if {
	some i, r in separation_records
	separation_record_incomplete(r)
}

separation_record_incomplete(r) if not has_value(r, "date")

separation_record_incomplete(r) if not has_value(r, "volume_m3")

violations contains {"rule_id": "O69-GEN-021", "message": "Beantragte separierte Menge übersteigt die aufgezeichnete Menge"} if {
	count(separation_records) > 0
	separated_volume_claimed > sum([object.get(r, "volume_m3", 0) | some r in separation_records])
}

violations contains {"rule_id": "O69-MB-024", "message": "Einsatz betriebsfremder Separationsgeräte ohne Rechnung oder geeignete Unterlagen"} if {
	is_true(separation, "contractor_used")
	not is_true(separation, "contractor_invoice_available")
}

violations contains {"rule_id": "O69-MB-025", "message": "Gemeinschaftlich angeschaffter Separator: nicht kontrollierbar oder Rechnung nicht an teilnehmende Betriebe ausgestellt"} if {
	shared := object.get(separation, "shared_equipment", {})
	is_true(shared, "used")
	shared_equipment_conditions_unmet(shared)
}

